package ktanesolver.module.modded.regular.theradio;import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.*;
class TheRadioSolverTest{private final TheRadioSolver solver=new TheRadioSolver();
	@Test void appliesCountryPriority(){assertThat(TheRadioSolver.country(5,5)).isEqualTo("Dutch");assertThat(TheRadioSolver.country(2,2)).isEqualTo("English");assertThat(TheRadioSolver.country(4,1)).isEqualTo("German");assertThat(TheRadioSolver.country(1,2)).isEqualTo("French");}
	@Test void choosesFirstMatchingChannelWithinCountry(){assertThat(TheRadioSolver.channel("Dutch","SAA23").name()).isEqualTo("Q-Music");assertThat(TheRadioSolver.channel("English","DDD23").name()).isEqualTo("Radio X");assertThat(TheRadioSolver.channel("German","CCC23").name()).isEqualTo("Klassik Radio");assertThat(TheRadioSolver.channel("French","BAA23").name()).isEqualTo("Jazz Radio");}
	@Test void derivesFrequencyTransmissionTimingAndRobustCommands(){BombEntity bomb=bomb("Z9A1B2",3,0,1);TheRadioOutput out=solve(bomb,new TheRadioInput("RA-D-IO: NAA73",20,"AM"));assertThat(out.country()).isEqualTo("Dutch");assertThat(out.channelName()).isEqualTo("NPO1");assertThat(out.frequency()).isEqualTo("91.8");assertThat(out.transmission()).isEqualTo("FM");assertThat(out.transmitAt()).isEqualTo("07");assertThat(out.commands()).containsExactly("reset","channel down 16","switch","transmit at 07");}
	@Test void usesSourceBatteryModuloTenAndStrictTransmissionComparisons(){BombEntity bomb=bomb("A1B2C1",12,0,1);TheRadioOutput out=solve(bomb,new TheRadioInput("WWW55",6,"AM"));assertThat(out.country()).isEqualTo("German");assertThat(out.transmitAt()).isEqualTo("02");assertThat(out.transmission()).isEqualTo("AM");assertThat(out.commands()).containsExactly("reset","channel up 5","transmit at 02");}
	@Test void rejectsImpossibleFactoryObservations(){assertThat(solver.solve(new RoundEntity(),bomb("A1B2C3",2,0,1),new ModuleEntity(),new TheRadioInput("XYZ12",0,"SW"))).isInstanceOf(SolveFailure.class);}
	private TheRadioOutput solve(BombEntity bomb,TheRadioInput input){return((SolveSuccess<TheRadioOutput>)solver.solve(new RoundEntity(),bomb,new ModuleEntity(),input)).output();}private static BombEntity bomb(String serial,int aa,int d,int ignored){BombEntity bomb=new BombEntity();bomb.setSerialNumber(serial);bomb.setAaBatteryCount(aa);bomb.setDBatteryCount(d);return bomb;}}
